  // the main workflow sets workflow_status to 'stopped' on drain.
  out.workflow_status = 'stopped';
  out.current_run_id = live.current_run_id || null;
} else if (verb === 'pause') {
  const off = p.action.includes('off');
  out.paused = off ? false : true;
  out.pause_reason = off ? '' : (p.args && p.args.reason ? p.args.reason : 'operator pause');
  return finish(out, live.paused ?? '—', out.paused);
} else if (verb === 'restart') {
  // stop, wait for the active run to drain, then start again from saved state.
  out.workflow_status = 'starting';
  out.current_run_id = live.current_run_id || null;
} else if (verb === 'steer') {
  const note = p.args && p.args.prompt ? p.args.prompt : '';
  out.steer_note = (live.operator_feedback ? live.operator_feedback + '\n' : '') + note;
  return finish(out, live.operator_feedback ?? '—', out.steer_note);
} else if (verb === 'queue') {
  const op = p.args && p.args.op ? p.args.op : 'list';
  const q = live.queue || [];
  if (op === 'add') { q.push(p.args && p.args.mission ? p.args.mission : ''); }
  else if (op === 'list') { out.queue = q; }
  else if (op === 'rm') { const idx = Number(p.args && p.args.index); if (Number.isFinite(idx)) q.splice(idx, 1); }
  else if (op === 'move') { const a = Number(p.args && p.args.a), b = Number(p.args && p.args.b); if (Number.isFinite(a) && Number.isFinite(b) && a < q.length && b < q.length) { [q[a], q[b]] = [q[b], q[a]]; } }
  else if (op === 'clear') { q.length = 0; }
  out.queue = q;
  return finish(out, JSON.stringify(live.queue || []), JSON.stringify(q));
}
// record intent + owner for other control verbs (resume, retry, accept, start)
out.last_control = p.action;
return finish(out, statusBefore, out.last_control);

const a = $json.audit ?? null;
if (!a) return [];
const row = { who: a.who, when: a.when, command: a.command, before: a.before, after: a.after, result: a.result, reason: a.reason ?? '' };
return [{ json: row }];
